#!/usr/bin/env node
// PreToolUse (Edit|Write|MultiEdit|NotebookEdit): deny edits to generated files and
// say which command regenerates them. CI enforces the same rules (template drift,
// bundle check, check:ai-drift); this just fails fast inside Claude Code.

import { readFileSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "../..");
// The header comment sync-ai-config.ts writes near the top of every adapter (after any
// frontmatter). Matching only that form keeps the generator and this hook editable.
const AI_MARKER = /^<!-- Generated by scripts\/sync-ai-config\.ts/m;

const RULES = [
  {
    match: (p) => p.startsWith("packages/create-one-terminal/templates/"),
    fix: "Edit the live source in apps/ or packages/ot-*, then run `npm run create-migration` (or `npm run extract-templates`).",
  },
  {
    match: (p) => p === "packages/create-one-terminal/static-manifest.json",
    fix: "It is written by `npm run extract-templates`.",
  },
  {
    match: (p) => p === "packages/fdc3-plugin/fdc3-plugin.js",
    fix: "Edit packages/fdc3-plugin/src/, then run `npm run build:fdc3-plugin`.",
  },
];

function deny(path, fix) {
  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: `${path} is generated — don't edit it by hand. ${fix}`,
      },
    })
  );
  process.exit(0);
}

let input;
try {
  input = JSON.parse(readFileSync(0, "utf8"));
} catch {
  process.exit(0);
}
const file = input?.tool_input?.file_path ?? input?.tool_input?.notebook_path;
if (!file) process.exit(0);

const rel = relative(ROOT, file).split(sep).join("/");
if (rel.startsWith("../")) process.exit(0);

for (const rule of RULES) {
  if (rule.match(rel)) deny(rel, rule.fix);
}

let current = null;
try {
  current = readFileSync(join(ROOT, rel), "utf8");
} catch {
  // new file — nothing generated to protect
}
// Agent adapters put the marker after a frontmatter block, so look past it.
if (current && AI_MARKER.test(current.slice(0, 4000))) {
  const source = rel.endsWith("CLAUDE.md")
    ? rel.replace(/CLAUDE\.md$/, "AGENTS.md")
    : "the AGENTS.md it names in its header";
  deny(rel, `Edit ${source}, then run \`npm run sync:ai\`.`);
}
